import base64, hashlib, os, pathlib, subprocess
REPO = pathlib.Path('/content/osr1')
SRC_B64 = ''
target = REPO / 'YangMills/OS/OSReconstructionUniform.lean'
target.write_bytes(base64.b64decode(SRC_B64))
print('SOURCE', target.stat().st_size, hashlib.sha256(target.read_bytes()).hexdigest(), flush=True)
env = {**os.environ, 'PATH': '/root/.elan/bin:' + os.environ['PATH']}
p = subprocess.run(['lake', 'env', 'lean', 'YangMills/OS/OSReconstructionUniform.lean'],
                   cwd=REPO, text=True, stdout=subprocess.PIPE,
                   stderr=subprocess.STDOUT, timeout=1800, env=env)
print('ELAB_EXIT', p.returncode, flush=True)
print(p.stdout[-12000:], flush=True)
